// Tolerant of both `&` and `?` separators: some hosted redirects append `?token`
// onto a callback that already carried `?state`, yielding `state=..?token=..`.
// Values come back exactly as they arrived; tokens must round-trip verbatim.
function queryParam(query: string, key: string): string | undefined {
  for (const pair of query.split(/[&?]/)) {
    const equals = pair.indexOf("=");
    if ((equals === -1 ? pair : pair.slice(0, equals)) !== key) continue;
    return equals === -1 ? undefined : pair.slice(equals + 1);
  }
  return undefined;
}

/** Decodes human-readable query text (OAuth error descriptions), never tokens. */
function decodeQueryText(value: string): string {
  const spaced = value.replace(/\+/g, " ");
  try {
    return decodeURIComponent(spaced);
  } catch {
    // Malformed percent escapes are the login page's problem, not a reason to
    // swallow the only explanation the user is going to get.
    return spaced;
  }
}

// Turns a failed handoff (`?error=...`) into a sentence worth showing. Capped
// because it lands in both the browser page and the terminal.
function callbackFailure(query: string): string | undefined {
  const error = queryParam(query, "error");
  if (!error) return undefined;
  if (error === "access_denied") return "Sign-in was cancelled before it finished.";
  const description = decodeQueryText(queryParam(query, "error_description") ?? "");
  const message = description
    || `The login page reported an error: ${decodeQueryText(error)}`;
  return message.slice(0, 200);
}

export interface OAuthCallbackServer {
  /** The bound port — only final once {@link ready} has resolved. */
  readonly port: number;
  /** Resolves once the socket is bound and accepting requests. */
  ready: Promise<void>;
  /** The raw, unverified token from the callback; rejects on error or cancel. */
  token: Promise<string>;
  close(): void;
}

/**
 * The loopback listener the browser hands the session back to. Answers the
 * hosted login page's `/auth/ping` readiness probe and turns
 * `/auth/callback?token=...` into a resolved token plus a page telling the user
 * the tab is done.
 *
 * Deliberately dumber than the overlay's Rust equivalent
 * (`tauri/src/main.rs`, `handle_callback_connection`), which is handed the
 * `expected_state` nonce it generated itself: this takes only a port, so it has
 * no nonce to compare `state` against and accepts the token as received.
 * Verifying it belongs to a real account is the caller's job.
 */
export function startOAuthCallbackServer(port: number): OAuthCallbackServer {
  let settle: (token: string) => void = () => {};
  let fail: (error: Error) => void = () => {};
  const token = new Promise<string>((resolve, reject) => {
    settle = resolve;
    fail = reject;
  });
  // A stale tab can fail the handoff when nobody is awaiting `token` any more;
  // an inert handler keeps that from surfacing as an unhandled rejection.
  token.catch(() => {});

  const server = createServer((request, response) => {
    const target = request.url ?? "/";
    const split = target.indexOf("?");
    const path = split === -1 ? target : target.slice(0, split);
    const query = split === -1 ? "" : target.slice(split + 1);

    const reply = (status: number, contentType: string, body: string): void => {
      response.writeHead(status, {
        "content-type": contentType,
        "content-length": Buffer.byteLength(body),
        // Pages carry a session token in their URL — keep them out of caches
        // and out of the Referer sent to anything they link to.
        "cache-control": "no-store",
        "referrer-policy": "no-referrer",
        connection: "close",
      });
      response.end(body);
    };

    if (path === "/auth/ping") {
      reply(200, "text/plain; charset=utf-8", "ok");
      return;
    }
    if (path !== "/auth/callback") {
      reply(404, "text/plain; charset=utf-8", "not found");
      return;
    }
    // A login page that gave up hands back `error` instead of `token`; saying
    // why beats the generic "did not return a session token".
    const reason = callbackFailure(query)
      ?? (queryParam(query, "token")
        ? undefined
        : "The login page came back without a session token.");
    if (reason) {
      reply(400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(reason)));
      fail(new Error(reason));
      return;
    }
    reply(200, "text/html; charset=utf-8", signedInPage());
    settle(queryParam(query, "token")!);
  });

  const ready = new Promise<void>((resolve, reject) => {
    let retried = false;
    server.on("listening", resolve);
    server.on("error", (error: Error & { code?: string }) => {
      if (!retried && (error.code === "EADDRINUSE" || error.code === "EACCES")) {
        // Something else already holds the preferred port. The Worker only
        // requires a loopback callback, not a fixed one, so any free port does.
        retried = true;
        server.listen(0, "127.0.0.1");
        return;
      }
      reject(error);
      fail(error);
    });
    server.listen(port, "127.0.0.1");
  });
  ready.catch(() => {});

  return {
    get port(): number {
      const address = server.address();
      return typeof address === "object" && address ? address.port : port;
    },
    ready,
    token,
    close(): void {
      server.close();
      // A browser keeping the connection alive would otherwise hold the process
      // open well past the sign-in it was serving.
      (server as { closeAllConnections?: () => void }).closeAllConnections?.();
    },
  };
}

/**
 * Arc (and Dia, same vendor) route links from other apps into a "Little Arc"
 * window, which drops the hosted login page's redirect chain — the tab either
 * never appears or dies mid-handoff, so sign-in silently never completes.
 * Asking Arc for a real tab in a real window over AppleScript bypasses Little
 * Arc entirely. Mirrors `is_arc_bundle` in `tauri/src/main.rs`.
 */
export function isArcBundle(bundleId: string): boolean {
  const id = bundleId.toLowerCase();
  return id === "company.thebrowser.browser" || id === "company.thebrowser.dia";
}

function applescriptEscape(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

/** The AppleScript that opens `url` as a real tab in a real Arc/Dia window. */
export function arcTabScript(bundleId: string, url: string): string {
  return `tell application id "${applescriptEscape(bundleId)}"
    activate
    if (count of windows) is 0 then
        make new window
    end if
    tell front window to make new tab with properties {URL:"${applescriptEscape(url)}"}
end tell`;
}

/**
 * Runs an opener and reports whether it actually succeeded. Spawning alone
 * can't tell us that — `xdg-open` with no handler and `open` with a broken
 * default browser both fail *after* the spawn — so we wait for the exit status.
 * Every opener returns promptly, so this doesn't stall the sign-in noticeably.
 */
function runOpener(command: string, args: string[]): boolean {
  try {
    return spawnSync(command, args, { stdio: "ignore" }).status === 0;
  } catch {
    return false;
  }
}

/**
 * `defaults read` prints one dict per registered handler; the role and the
 * scheme are separate lines inside the same `{ ... }` block, so we scan block
 * by block for the one claiming `https`.
 */
function parseDefaultHttpsHandler(plist: string): string | undefined {
  for (const block of plist.split("{")) {
    if (!block.includes("LSHandlerURLScheme = https;")) continue;
    const line = block.split("\n").find((entry) =>
      entry.trimStart().startsWith("LSHandlerRoleAll = ")
    );
    if (!line) continue;
    const value = line.trim()
      .slice("LSHandlerRoleAll = ".length)
      .replace(/;$/, "")
      .replace(/^"|"$/g, "");
    if (value) return value;
  }
  return undefined;
}

