 * The bundle id macOS would hand an `https` URL to, read from LaunchServices.
 * Used only to detect Arc (see {@link arcTabScript}); any parse failure just
 * means we take the ordinary `open` path.
 */
function defaultHttpsHandler(): string | undefined {
  try {
    const result = spawnSync(
      "defaults",
      ["read", "com.apple.LaunchServices/com.apple.launchservices.secure"],
      { encoding: "utf8" },
    );
    if (result.status !== 0 || !result.stdout) return undefined;
    return parseDefaultHttpsHandler(result.stdout);
  } catch {
    return undefined;
  }
}

/**
 * Hands the login URL to the user's browser. Returns false when every opener we
 * know about failed — the CLI then leads with the fallback link instead of
 * claiming a browser is opening.
 */
function openBrowser(url: string): boolean {
  if (process.platform === "darwin") {
    const bundleId = defaultHttpsHandler();
    if (
      bundleId && isArcBundle(bundleId)
      && runOpener("osascript", ["-e", arcTabScript(bundleId, url)])
    ) {
      return true;
    }
    // Safari is the last resort: it is always present, so a broken or missing
    // default handler still gets the user to the login page.
    return runOpener("open", [url]) || runOpener("open", ["-a", "Safari", url]);
  }
  if (process.platform === "win32") {
    return runOpener("cmd", ["/c", "start", "", url])
      || runOpener("rundll32", ["url.dll,FileProtocolHandler", url]);
  }
  return runOpener("xdg-open", [url])
    || runOpener("gio", ["open", url])
    || runOpener("x-www-browser", [url]);
}

function oauthUrl(provider: OAuthProvider, callbackUrl: string): string {
  const url = new URL(`${requireAuthBaseUrl()}/cli/oauth`);
  url.searchParams.set("provider", provider);
  url.searchParams.set("next", callbackUrl);
  return url.toString();
}

/** Gives up on the browser rather than owning the terminal indefinitely. */
async function awaitToken(token: Promise<string>): Promise<string> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      token,
      new Promise<never>((_resolve, reject) => {
        timer = setTimeout(
          () => reject(new Error("Timed out waiting for the browser sign-in to finish.")),
          oauthTimeoutMs,
        );
      }),
    ]);
  } finally {
    clearTimeout(timer);
  }
}

async function runOAuthSignIn(provider: OAuthProvider): Promise<AuthSuccess> {
  const label = provider === "google" ? "Google" : "GitHub";
  const callback = startOAuthCallbackServer(defaultCallbackPort);
  try {
    await callback.ready;
    const loginUrl = oauthUrl(provider, `http://127.0.0.1:${callback.port}/auth/callback`);
    console.log(
      openBrowser(loginUrl)
        ? `Opening your browser to sign in with ${label}. If nothing opened, use this link:`
        : `Could not open a browser. Finish signing in with ${label} at:`,
    );
    console.log(`  ${loginUrl}`);
    const sessionToken = await awaitToken(callback.token);
    const user = await resolveUser(sessionToken);
    saveSession(sessionToken, user);
    console.log(`Signed in as ${user.email}`);
    return { kind: "signed_in", method: provider, userId: user.id };
  } finally {
    callback.close();
  }
}

export type { AuthUser, StoredSession };

