test("oauth rejects a provider the worker would not sign in with", async () => {
  await expect(runAuthCommand("oauth", "twitter")).rejects.toThrow(/google\|github/);
  await expect(runAuthCommand("oauth")).rejects.toThrow(/google\|github/);
});

test("the callback listener answers the readiness probe and hands back the token", async () => {
  const callback = startOAuthCallbackServer(0);
  await callback.ready;
  try {
    const ping = await fetch(`http://127.0.0.1:${callback.port}/auth/ping`);
    expect(ping.status).toBe(200);
    expect(await ping.text()).toBe("ok");

    // The hosted redirect glues `?token` onto a callback that already carried
    // `?state`, so the parser has to read `?` as another separator.
    const landing = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?state=nonce-1?token=session-secret`,
    );
    expect(landing.status).toBe(200);
    expect(landing.headers.get("cache-control")).toBe("no-store");
    expect(await landing.text()).toContain("signed in");
    await expect(callback.token).resolves.toBe("session-secret");
  } finally {
    callback.close();
  }
});

test("the callback listener falls back to a free port when its own is taken", async () => {
  const squatter = createServer();
  await new Promise<void>((resolve) => squatter.listen(3210, "127.0.0.1", resolve));
  const callback = startOAuthCallbackServer(3210);
  try {
    await callback.ready;
    expect(callback.port).not.toBe(3210);
    expect((await fetch(`http://127.0.0.1:${callback.port}/auth/ping`)).status).toBe(200);
  } finally {
    callback.close();
    squatter.close();
  }
});

test("a cancelled sign-in fails the attempt and says so in the page", async () => {
  const callback = startOAuthCallbackServer(0);
  await callback.ready;
  try {
    const landing = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?error=access_denied`,
    );
    expect(landing.status).toBe(400);
    expect(await landing.text()).toMatch(/cancelled/i);
    await expect(callback.token).rejects.toThrow(/cancelled/i);
  } finally {
    callback.close();
  }
});

test("a failed sign-in escapes the provider's reason but reports it raw", async () => {
  const callback = startOAuthCallbackServer(0);
  await callback.ready;
  try {
    const landing = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?error=server_error`
        + `&error_description=${encodeURIComponent("<script>alert(1)</script> failed")}`,
    );
    expect(landing.status).toBe(400);
    const body = await landing.text();
    expect(body).not.toContain("<script>alert(1)</script>");
    expect(body).toContain("&lt;script&gt;alert(1)&lt;/script&gt; failed");
    await expect(callback.token).rejects.toThrow("<script>alert(1)</script> failed");
  } finally {
    callback.close();
  }
});

test("a callback with no token at all still explains itself", async () => {
  const callback = startOAuthCallbackServer(0);
  await callback.ready;
  try {
    const landing = await fetch(`http://127.0.0.1:${callback.port}/auth/callback?state=nonce-1`);
    expect(landing.status).toBe(400);
    expect(await landing.text()).toContain("without a session token");
    await expect(callback.token).rejects.toThrow(/without a session token/);
  } finally {
    callback.close();
  }
});

test("Arc and Dia get a real tab, and the script cannot be escaped out of", () => {
  expect(isArcBundle("company.thebrowser.Browser")).toBe(true);
  expect(isArcBundle("company.thebrowser.dia")).toBe(true);
  expect(isArcBundle("com.apple.Safari")).toBe(false);

  const script = arcTabScript("company.thebrowser.Browser", 'http://127.0.0.1:3210/a"\\b');
  expect(script).toContain('tell application id "company.thebrowser.Browser"');
  expect(script).toContain("make new tab with properties {URL:");
  expect(script).toContain('http://127.0.0.1:3210/a\\"\\\\b');
});

