import { getMigrations } from "better-auth/db/migration";
import {
  createAuth,
  isOAuthProvider,
  providerCredentials,
  trustedOrigins,
  type AuthEnv,
  type OAuthProvider,
} from "./auth";
import { handoffProblemPage, handoffRedirectPage, signInRequiredPage } from "./handoff-page";

/** better-auth's default session cookie name. */
const SESSION_COOKIE = "better-auth.session_token";

function htmlResponse(status: number, body: string): Response {
  return new Response(body, {
    status,
    headers: {
      "content-type": "text/html; charset=utf-8",
      // These pages carry (or lead to) a session token — keep them out of
      // caches and out of the Referer sent onward.
      "cache-control": "no-store",
      "referrer-policy": "no-referrer",
    },
  });
}

/**
 * The CLI listener this sign-in is allowed to hand a session to. Only a plain
 * `http` loopback URL qualifies: the token is appended to whatever comes back
 * from here, so an attacker-supplied `next` would otherwise turn either CLI
 * endpoint into a redirector that leaks a live session off the machine.
 */
function localCallbackTarget(next: string | null): URL | null {
  if (!next) return null;
  let parsed: URL;
  try {
    parsed = new URL(next);
  } catch {
    return null;
  }
  if (parsed.protocol !== "http:") return null;
  if (parsed.hostname !== "127.0.0.1" && parsed.hostname !== "localhost") return null;
  return parsed;
}

function rejectNext(): Response {
  return htmlResponse(
    400,
    handoffProblemPage(
      "That sign-in link points somewhere Tui will not hand a session to.",
      [
        "Tui only signs in to a listener on your own machine — an <code>http://127.0.0.1</code> or <code>http://localhost</code> address.",
        "Start the sign-in from your terminal with <code>gamepigeon auth oauth google</code> so the link is built for you.",
      ],
    ),
  );
}

/** The literal session token the browser is holding, straight off the cookie. */
function sessionTokenFromCookie(header: string | null): string | null {
  if (!header) return null;
  for (const part of header.split(";")) {
    const separator = part.indexOf("=");
    if (separator === -1) continue;
    const name = part.slice(0, separator).trim();
    // `__Secure-` is the same cookie: better-auth prefixes it when it is
    // setting cookies over HTTPS, which production always is.
    if (name !== SESSION_COOKIE && name !== `__Secure-${SESSION_COOKIE}`) continue;
    const value = part.slice(separator + 1).trim();
    if (value) return value;
  }
  return null;
}

/**
 * Starts a browser sign-in for the CLI. The provider redirect chain comes back
 * to `/cli/handoff`, which is what actually reaches `next`.
 */
async function startCliOAuth(request: Request, url: URL, env: AuthEnv): Promise<Response> {
  const provider = url.searchParams.get("provider");
  if (!isOAuthProvider(provider)) {
    return htmlResponse(
      400,
      handoffProblemPage(
        "Tui can only sign in with Google or GitHub in the browser.",
        ["Run <code>gamepigeon auth oauth google</code> or <code>gamepigeon auth oauth github</code>."],
      ),
    );
  }
  if (!providerCredentials(env, provider)) {
    return htmlResponse(
      503,
      handoffProblemPage(
        `Signing in with ${providerLabel(provider)} is not configured on this server yet.`,
        ["Try the other provider, or <code>gamepigeon auth login</code> with an email and password."],
      ),
    );
  }
  const next = localCallbackTarget(url.searchParams.get("next"));
  if (!next) return rejectNext();

  const handoff = new URL("/cli/handoff", env.BETTER_AUTH_URL);
  handoff.searchParams.set("next", next.toString());

  let signIn: Response;
  try {
    signIn = await createAuth(env).api.signInSocial({
      body: {
        provider,
        callbackURL: handoff.toString(),
        // Failures go straight to the CLI listener, which turns `error` into a
        // sentence in the terminal instead of a dead-end browser page.
        errorCallbackURL: next.toString(),
      },
      headers: request.headers,
      asResponse: true,
    });
  } catch {
    return htmlResponse(
      503,
      handoffProblemPage(`${providerLabel(provider)} sign-in could not be started.`),
    );
  }
  const authorizeUrl = ((await signIn.json()) as { url?: string }).url;
  if (!authorizeUrl) {
    return htmlResponse(
      503,
      handoffProblemPage(`${providerLabel(provider)} did not return a sign-in page.`),
    );
  }

  const headers = new Headers({
    location: authorizeUrl,
    "cache-control": "no-store",
    "referrer-policy": "no-referrer",
  });
  // The OAuth state lives in a cookie (see `account.storeStateStrategy`), so the
  // redirect has to carry the cookies better-auth just set or the callback fails.
  for (const cookie of signIn.headers.getSetCookie()) headers.append("set-cookie", cookie);
  return new Response(null, { status: 302, headers });
}

function providerLabel(provider: OAuthProvider): string {
  return provider === "google" ? "Google" : "GitHub";
}

/**
 * Hands the browser's signed-in session back to the CLI listener named by
 * `next`, keeping that URL's own query (the CLI may have put a nonce there).
 */
async function handOffToCli(request: Request, url: URL, env: AuthEnv): Promise<Response> {
  const next = localCallbackTarget(url.searchParams.get("next"));
  if (!next) return rejectNext();

  const session = await createAuth(env).api.getSession({ headers: request.headers });
  const token = sessionTokenFromCookie(request.headers.get("cookie"));
  if (!session?.user || !token) return htmlResponse(401, signInRequiredPage());

  const target = new URL(next.toString());
  target.searchParams.append("token", token);
  return htmlResponse(200, handoffRedirectPage(target.toString()));
}

function authCors(request: Request, response: Response, env: AuthEnv): Response {
  const origin = request.headers.get("origin");
  if (!origin || !trustedOrigins(env).includes(origin)) return response;
  const headers = new Headers(response.headers);
  headers.set("access-control-allow-origin", origin);
  headers.set("access-control-allow-credentials", "true");
  headers.set("access-control-expose-headers", "set-auth-token");
  headers.append("vary", "Origin");
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
}

export default {
  async fetch(request: Request, env: AuthEnv): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname.startsWith("/api/auth/") && request.method === "OPTIONS") {
      const origin = request.headers.get("origin");
      if (!origin || !trustedOrigins(env).includes(origin)) return new Response(null, { status: 403 });
      return authCors(request, new Response(null, {
        status: 204,
        headers: {
          "access-control-allow-headers": "content-type, authorization",
          "access-control-allow-methods": "GET, POST, OPTIONS",
        },
      }), env);
    }

    if (url.pathname === "/migrate" && request.method === "POST") {
      if (
        !env.MIGRATION_SECRET
        || request.headers.get("authorization") !== `Bearer ${env.MIGRATION_SECRET}`
      ) {
        return Response.json(
          { error: "Unauthorized" },
          { status: 401, headers: { "www-authenticate": "Bearer" } },
        );
      }
      const auth = createAuth(env);
      const { toBeCreated, toBeAdded, runMigrations } = await getMigrations(auth.options);
      if (toBeCreated.length === 0 && toBeAdded.length === 0) {
        return Response.json({ message: "No migrations needed" });
      }
      await runMigrations();
      return Response.json({
        message: "Migrations completed",
        created: toBeCreated.map((table) => table.table),
        added: toBeAdded.map((table) => table.table),
      });
    }

    if (url.pathname === "/cli/oauth" && request.method === "GET") {
      return startCliOAuth(request, url, env);
    }

    if (url.pathname === "/cli/handoff" && request.method === "GET") {
      return handOffToCli(request, url, env);
    }

    if (url.pathname === "/" && request.method === "GET") {
      return Response.json({
        service: "tui-gamepigeon-auth",
        ok: true,
        authBasePath: "/api/auth",
      });
    }

    return authCors(request, await createAuth(env).handler(request), env);
  },
} satisfies ExportedHandler<AuthEnv>;

