test("auth oauth saves the session the browser hands to the listener", async () => {
  const testHome = mkdtempSync(join(tmpdir(), "gamepigeon-auth-"));
  process.env.HOME = testHome;
  process.env.GAMEPIGEON_AUTH_URL = "https://auth.example";
  globalThis.fetch = Object.assign(
    async (input: RequestInfo | URL, init?: RequestInit) => {
      const target = String(input instanceof Request ? input.url : input);
      if (target.startsWith("http://127.0.0.1")) return fetch(input as string, init);
      expect(target).toBe("https://auth.example/api/auth/get-session");
      expect(new Headers(init?.headers).get("authorization")).toBe("Bearer handed-off-token");
      return new Response(
        JSON.stringify({ user: { id: "usr_oauth", email: "person@example.com" } }),
        { status: 200 },
      );
    },
    { preconnect: fetch.preconnect },
  );
  const logged: string[] = [];
  const log = console.log;
  console.log = (...parts: unknown[]) => void logged.push(parts.join(" "));

  try {
    const signIn = runAuthCommand("oauth", "google");
    // The printed fallback link is the same URL the browser was handed, so it
    // names the listener the callback has to come back to.
    const loginUrl = await Promise.race([
      (async () => {
        for (let attempt = 0; attempt < 100; attempt += 1) {
          const printed = logged.find((line) => line.includes("/cli/oauth?"));
          if (printed) return new URL(printed.trim());
          await Bun.sleep(10);
        }
        throw new Error(`never printed a login URL: ${logged.join("\n")}`);
      })(),
      signIn.then(() => {
        throw new Error("sign-in finished before the browser was sent anywhere");
      }),
    ]);

    expect(loginUrl.origin).toBe("https://auth.example");
    expect(loginUrl.pathname).toBe("/cli/oauth");
    expect(loginUrl.searchParams.get("provider")).toBe("google");
    const next = new URL(loginUrl.searchParams.get("next")!);
    expect(next.protocol).toBe("http:");
    expect(next.hostname).toBe("127.0.0.1");
    expect(next.pathname).toBe("/auth/callback");

    await fetch(`${next.toString()}?token=handed-off-token`);
    await expect(signIn).resolves.toEqual({
      kind: "signed_in",
      method: "google",
      userId: "usr_oauth",
    });
    expect(JSON.parse(readFileSync(join(testHome, ".tui-gamepigeon", "auth.json"), "utf8")))
      .toEqual({ sessionToken: "handed-off-token", user: { id: "usr_oauth", email: "person@example.com" } });
  } finally {
    console.log = log;
    rmSync(testHome, { recursive: true, force: true });
  }
});

