100	 * Starts a browser sign-in for the CLI. The provider redirect chain comes back
101	 * to `/cli/handoff`, which is what actually reaches `next`.
102	 */
103	async function startCliOAuth(request: Request, url: URL, env: AuthEnv): Promise<Response> {
104	  const provider = url.searchParams.get("provider");
105	  if (!isOAuthProvider(provider)) {
106	    return htmlResponse(
107	      400,
108	      handoffProblemPage(
109	        "Tui can only sign in with Google or GitHub in the browser.",
110	        ["Run <code>gamepigeon auth oauth google</code> or <code>gamepigeon auth oauth github</code>."],
111	      ),
112	    );
113	  }
114	  if (!providerCredentials(env, provider)) {
115	    return htmlResponse(
116	      503,
117	      handoffProblemPage(
118	        `Signing in with ${providerLabel(provider)} is not configured on this server yet.`,
119	        ["Try the other provider, or <code>gamepigeon auth login</code> with an email and password."],
120	      ),
121	    );
122	  }
123	  const next = localCallbackTarget(url.searchParams.get("next"));
124	  if (!next) return rejectNext();
125	
126	  const handoff = new URL("/cli/handoff", env.BETTER_AUTH_URL);
127	  handoff.searchParams.set("next", next.toString());
128	
129	  let signIn: Response;
130	  try {
131	    signIn = await createAuth(env).api.signInSocial({
132	      body: {
133	        provider,
134	        callbackURL: handoff.toString(),
135	        // Failures go straight to the CLI listener, which turns `error` into a
136	        // sentence in the terminal instead of a dead-end browser page.
137	        errorCallbackURL: next.toString(),
138	      },
139	      headers: request.headers,
140	      asResponse: true,
141	    });
142	  } catch {
143	    return htmlResponse(
144	      503,
145	      handoffProblemPage(`${providerLabel(provider)} sign-in could not be started.`),
146	    );
147	  }
148	  const authorizeUrl = ((await signIn.json()) as { url?: string }).url;
149	  if (!authorizeUrl) {
150	    return htmlResponse(
151	      503,
152	      handoffProblemPage(`${providerLabel(provider)} did not return a sign-in page.`),
153	    );
154	  }
155	
156	  const headers = new Headers({
157	    location: authorizeUrl,
158	    "cache-control": "no-store",
159	    "referrer-policy": "no-referrer",
160	  });
161	  // The OAuth state lives in a cookie (see `account.storeStateStrategy`), so the
162	  // redirect has to carry the cookies better-auth just set or the callback fails.
163	  for (const cookie of signIn.headers.getSetCookie()) headers.append("set-cookie", cookie);
164	  return new Response(null, { status: 302, headers });
165	}
