toolUseResult.originalFile:
import { getMigrations } from "better-auth/db/migration";
import { env } from "cloudflare:workers";
import { beforeAll, expect, test } from "vitest";
import { createAuth, type AuthEnv } from "../src/auth";
import worker from "../src/index";

const WORKER_ORIGIN = env.BETTER_AUTH_URL;
const CLI_CALLBACK = "http://127.0.0.1:3210/auth/callback?state=nonce-1";

/** The environment an operator who configured Google sign-in would deploy. */
function withGoogle(): AuthEnv {
  return { ...env, GOOGLE_CLIENT_ID: "google-test-id", GOOGLE_CLIENT_SECRET: "google-test-secret" };
}

function get(path: string, init: RequestInit = {}, workerEnv: AuthEnv = env): Promise<Response> {
  return worker.fetch(new Request(`${WORKER_ORIGIN}${path}`, init), workerEnv);
}

function cliOAuth(query: string, workerEnv: AuthEnv = env): Promise<Response> {
  return get(`/cli/oauth?${query}`, {}, workerEnv);
}

function cliHandoff(next: string, cookie?: string): Promise<Response> {
  return get(
    `/cli/handoff?next=${encodeURIComponent(next)}`,
    cookie ? { headers: { cookie } } : {},
  );
}

test("/cli/oauth signs in with Google or GitHub and nothing else", async () => {
  for (const provider of ["twitter", "", "google-oauth"]) {
    expect((await cliOAuth(`provider=${provider}&next=${encodeURIComponent(CLI_CALLBACK)}`))
      .status).toBe(400);
  }
  expect((await cliOAuth(`next=${encodeURIComponent(CLI_CALLBACK)}`)).status).toBe(400);
});

test("/cli/oauth reports an unconfigured provider rather than failing mid-redirect", async () => {
  for (const provider of ["google", "github"]) {
    expect((await cliOAuth(`provider=${provider}&next=${encodeURIComponent(CLI_CALLBACK)}`))
      .status).toBe(503);
  }
  // Half-configured is unconfigured: the missing secret would only surface deep
  // inside the provider's redirect chain.
  const halfConfigured = { ...env, GOOGLE_CLIENT_ID: "google-test-id" };
  expect((await cliOAuth(`provider=google&next=${encodeURIComponent(CLI_CALLBACK)}`, halfConfigured))
    .status).toBe(503);
});

test("/cli/oauth refuses to start a sign-in for a callback off this machine", async () => {
  const rejected = [
    "https://evil.example/auth/callback",
    "http://evil.example/auth/callback",
    "http://127.0.0.1.evil.example/auth/callback",
    "javascript:alert(1)",
    "file:///etc/passwd",
    "/auth/callback",
    "",
  ];
  for (const next of rejected) {
    const response = await cliOAuth(`provider=google&next=${encodeURIComponent(next)}`, withGoogle());
    expect(response.status, next).toBe(400);
    expect(response.headers.get("location"), next).toBeNull();
  }
});

test("/cli/oauth redirects onward, carrying the state cookie the callback needs", async () => {
  const response = await cliOAuth(
    `provider=google&next=${encodeURIComponent(CLI_CALLBACK)}`,
    withGoogle(),
  );

  expect(response.status).toBe(302);
  const authorize = new URL(response.headers.get("location")!);
  expect(authorize.hostname).toBe("accounts.google.com");
  expect(authorize.searchParams.get("client_id")).toBe("google-test-id");
  // The provider comes back to the Worker, which is what reaches the CLI.
  expect(authorize.searchParams.get("redirect_uri")).toBe(`${WORKER_ORIGIN}/api/auth/callback/google`);
  expect(response.headers.getSetCookie().join("; ")).toContain("oauth_state");
  expect(response.headers.get("cache-control")).toBe("no-store");
});

test("/cli/handoff rejects a target off this machine before looking at the session", async () => {
  for (const next of ["https://evil.example/steal", "http://evil.example/steal", "not-a-url", ""]) {
    const response = await cliHandoff(next, "better-auth.session_token=session-secret");
    expect(response.status, next).toBe(400);
    expect(await response.text(), next).not.toContain("session-secret");
  }
});

test("/cli/handoff points a browser with no session at the sign-in command", async () => {
  const response = await cliHandoff(CLI_CALLBACK);

  expect(response.status).toBe(401);
  expect(await response.text()).toMatch(/oauth/i);
});

test("/cli/handoff wants a session, not just a cookie that looks like one", async () => {
  const response = await cliHandoff(CLI_CALLBACK, "better-auth.session_token=not-a-real-token");

  expect(response.status).toBe(401);
});

test("localhost is as local as 127.0.0.1", async () => {
  expect((await cliHandoff("http://localhost:49152/auth/callback")).status).toBe(401);
});

test("/cli/handoff hands a real session back to the waiting CLI listener", async () => {
  const { runMigrations } = await getMigrations(createAuth(env).options);
  await runMigrations();

  const signUp = await get("/api/auth/sign-up/email", {
    method: "POST",
    headers: { "content-type": "application/json", origin: WORKER_ORIGIN },
    body: JSON.stringify({
      email: "handoff@example.com",
      password: "correct-horse-battery-staple",
      name: "Handoff",
    }),
  });
  expect(signUp.status).toBe(200);
  const cookie = signUp.headers.getSetCookie()
    .map((value) => value.split(";")[0])
    .join("; ");
  const token = signUp.headers.get("set-auth-token");
  expect(token).toBeTruthy();

  const response = await cliHandoff(CLI_CALLBACK, cookie);
  expect(response.status).toBe(200);
  expect(response.headers.get("cache-control")).toBe("no-store");

  // The CLI listener reads the token straight out of the query, so the URL has
  // to reach the browser un-escaped, with the CLI's own `state` still on it.
  const body = await response.text();
  expect(body).toContain(`http://127.0.0.1:3210/auth/callback?state=nonce-1&token=${token}`);
  expect(body).toContain("location.replace(");
});
